package com.luminor.tavernquest.feature.quest.completion
import androidx.lifecycle.*;import com.luminor.tavernquest.domain.usecase.quest.*;import dagger.hilt.android.lifecycle.HiltViewModel;import javax.inject.Inject;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch
@HiltViewModel class QuestCompletionViewModel @Inject constructor(saved:SavedStateHandle,get:GetQuestUseCase,private val complete:CompleteQuestUseCase):ViewModel(){private val id:String=saved["id"]?:"";private val _ui=MutableStateFlow(QuestCompletionUiState());val ui=_ui.asStateFlow();init{viewModelScope.launch{_ui.update{it.copy(title=get(id)?.template?.title.orEmpty())}}};fun notes(v:String){_ui.update{it.copy(notes=v)}};fun photo(path:String?){_ui.update{it.copy(photoPath=path)}};fun finish(){viewModelScope.launch{_ui.update{it.copy(saving=true)};val ok=complete(id,_ui.value.notes,_ui.value.photoPath);_ui.update{it.copy(saving=false,completed=ok,error=if(ok)null else "Missão já concluída ou inválida.")}}}}
